import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as s,af as a}from"./chunks/mermaid.YsAH9es0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"MCP Security and Authorization Essentials","description":"Key security requirements from the MCP specification version 2026-07-28 - authorization, transport and state handling, and attack mitigations - with a checklist for server authors.","frontmatter":{"title":"MCP Security and Authorization Essentials","description":"Key security requirements from the MCP specification version 2026-07-28 - authorization, transport and state handling, and attack mitigations - with a checklist for server authors.","domain":"tech","tags":["protocol","mcp","security"]},"headers":[],"relativePath":"integration/protocols/mcp-security.md","filePath":"integration/protocols/mcp-security.md","lastUpdated":1793277967000}'),r={name:"integration/protocols/mcp-security.md"};function i(n,e,c,l,d,h){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="mcp-security-and-authorization-essentials" tabindex="-1">MCP Security and Authorization Essentials <a class="header-anchor" href="#mcp-security-and-authorization-essentials" aria-label="Permalink to &quot;MCP Security and Authorization Essentials&quot;">​</a></h1><p><strong>Bottom line</strong>: MCP authorization is OAuth-based and applies to HTTP-style transports. A server must accept only tokens issued for itself, must never pass client tokens upstream, and must validate <code>Origin</code> when it listens locally. The 2026-07-28 revision removes protocol-level sessions, so cross-request state needs handles that are unguessable and bound to an authenticated user.</p><blockquote><p><strong>Audience</strong>: engineers building or reviewing MCP servers and clients. <strong>Prerequisites</strong>: <a href="./mcp.html">MCP Implementation Guide</a> and basic OAuth 2.x vocabulary. <strong>Non-goal</strong>: this is not a replacement for the specification. Version scope: only specification version <strong>2026-07-28</strong> (page headers read &quot;latest&quot;), four pages, fetched 2026-10-21.</p></blockquote><p>Not covered because those pages were outside the fetch budget: the Authorization sub-pages (server discovery, client registration, security considerations) and the Client ID Metadata Document page. Some bold MUST sentences could not be matched verbatim and are not quoted here.</p><h2 id="authorization" tabindex="-1">Authorization <a class="header-anchor" href="#authorization" aria-label="Permalink to &quot;Authorization&quot;">​</a></h2><ul><li>Authorization support is optional. When supported, <strong>HTTP-based transports</strong> should follow this flow; stdio should obtain credentials from the environment instead. Other transports must follow their established security best practices.</li><li>Before starting the flow, a client must obtain a client ID through one of three mechanisms: Client ID Metadata Documents, pre-registration, or dynamic client registration.</li><li><strong>Scopes</strong>: follow least privilege. Servers should put a <code>scope</code> parameter in the <code>WWW-Authenticate</code> 401 challenge so clients know what to request. For step-up, request the union of previously requested scopes and the challenged scopes, so earlier grants are kept.</li><li><strong>Tokens</strong>: clients must implement RFC 8707 resource indicators, and the <code>resource</code> parameter identifies the target MCP server. Servers act as OAuth 2.1 resource servers and validate access tokens per section 5.2.</li><li><strong>Response validation</strong>: before sending an authorization code to any token endpoint, the client must perform the RFC 9207 check. This is the main mitigation for mix-up attacks.</li><li>Authorization-server implementation details are out of scope for the spec.</li></ul><h2 id="transport-and-state" tabindex="-1">Transport and state <a class="header-anchor" href="#transport-and-state" aria-label="Permalink to &quot;Transport and state&quot;">​</a></h2><ul><li>Protocol metadata travels in the message body under <code>_meta.io.modelcontextprotocol/*</code>. Streamable HTTP mirrors selected fields into headers, but the body stays the single source of truth. A server that processes the body must reject requests whose headers disagree with it.</li><li>Custom transports must keep the JSON-RPC message format, message schema and per-request metadata model.</li><li>Streamable HTTP servers <strong>must</strong> validate <code>Origin</code> and reject an invalid supplied origin with HTTP 403. The spec <strong>recommends</strong> localhost-only binding for local servers and authentication for all connections (SHOULD, rather than MUST). These protections address DNS rebinding from remote web pages.</li><li>2026-07-28 removes protocol-level sessions. Servers that need cross-request state issue their own <strong>handles</strong> (a cart ID, a workflow ID), and clients pass them back as ordinary tool arguments. Earlier revisions used connection-level sessions with an initialize handshake.</li></ul><h2 id="attacks-and-mitigations" tabindex="-1">Attacks and mitigations <a class="header-anchor" href="#attacks-and-mitigations" aria-label="Permalink to &quot;Attacks and mitigations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Attack</th><th>Description</th><th>Mitigation in the spec</th></tr></thead><tbody><tr><td>Confused deputy</td><td>A proxy MCP server uses a static client ID with a third-party authorization server. After one user consents, the consent cookie lets a newly registered malicious client skip the consent page, and the code goes to the attacker.</td><td>Implement <strong>per-client consent</strong>: keep a per-user registry of approved client IDs and check it before third-party authorization; show client name, scopes and redirect URI on the consent page; add CSRF and clickjacking protection; use random, single-use, short-lived <code>state</code>; match <code>redirect_uri</code> exactly; set consent cookies only <strong>after</strong> the user approves.</td></tr><tr><td>Token passthrough</td><td>A server accepts client tokens without checking they were issued for it and forwards them downstream.</td><td>Forbidden. Accept only tokens issued for this server, validate per OAuth 2.1 section 5.2, and use separate upstream tokens. Downstream rate limits and monitoring are otherwise bypassed.</td></tr><tr><td>SSRF during metadata discovery</td><td>A malicious server puts internal URLs in <code>resource_metadata</code>, <code>authorization_servers</code> or <code>token_endpoint</code>.</td><td>Require HTTPS for OAuth URLs in production (loopback excepted); block private, reserved and link-local ranges; do not write your own IP validation, because octal, hex and IPv4-mapped IPv6 encodings defeat custom parsers; validate redirects hop by hop; use an egress proxy on server deployments.</td></tr><tr><td>State handle hijacking</td><td>An attacker obtains or guesses a handle and reads or writes another user&#39;s state.</td><td>Never treat possession of a handle as authentication. Validate every inbound request, generate unpredictable handles, bind them server-side to the authenticated identity, and expire them.</td></tr><tr><td>Local server compromise</td><td>Malicious startup commands or payloads run with the client&#39;s privileges.</td><td>Require consent before running one-click configurations and show the full command without truncation. Run in a sandbox with least privilege and restricted file and network access. Use authorization tokens or restricted IPC for HTTP transports.</td></tr><tr><td>Mix-up</td><td>A malicious authorization server tricks the client into sending another server&#39;s code or token to it.</td><td>RFC 9207 issuer validation. PKCE alone is not enough, because the <code>code_verifier</code> goes to the attacker&#39;s token endpoint; resource indicators also do not help here.</td></tr><tr><td>Over-broad scopes</td><td>Listing every scope in <code>scopes_supported</code> makes tokens carry far more than an operation needs.</td><td>Request only necessary scopes and return precise scope guidance in challenges.</td></tr></tbody></table><p>The 2026-07-28 page points to the 2025-11-25 &quot;Session Hijacking&quot; section for servers that still allocate session IDs.</p><h2 id="checklist-for-mcp-server-authors" tabindex="-1">Checklist for MCP server authors <a class="header-anchor" href="#checklist-for-mcp-server-authors" aria-label="Permalink to &quot;Checklist for MCP server authors&quot;">​</a></h2><ol><li>Decide the transport first. HTTP-style transports use the authorization spec; others follow the protocol&#39;s security best practices.</li><li>Accept only tokens issued for your server, and validate them as an OAuth 2.1 resource server.</li><li>Never forward a client token to an upstream API.</li><li>Give 401 responses precise <code>scope</code> guidance, and support step-up with the union rule.</li><li>Validate the RFC 9207 issuer check before redeeming any authorization code.</li><li>Validate <code>Origin</code>, bind to localhost, and authenticate every connection when running locally.</li><li>Treat the request body as authoritative and reject header/body mismatches.</li><li>Bind state handles to the authenticated user, and make them unpredictable and expiring.</li><li>For proxy servers, implement per-client consent and set consent cookies only after approval.</li><li>In OAuth discovery, enforce HTTPS and block private ranges with a vetted library.</li></ol><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li>Believing a 127.0.0.1 binding is enough. Without Origin validation, DNS rebinding reaches it.</li><li>Relying on PKCE to stop mix-up attacks.</li><li>Treating a handle or session ID as proof of identity.</li><li>Writing custom IP filters.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Build a server in the <a href="./../../../examples/mcp-lab/README.html">MCP Lab example</a> and walk it through the checklist.</li><li>Read the 2025-11-25 Security Best Practices if you still support session-based clients.</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p>Fetched 2026-10-21, specification version 2026-07-28:</p><ul><li><a href="https://modelcontextprotocol.io/specification/2026-07-28/basic/authorization" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/2026-07-28/basic/authorization</a></li><li><a href="https://modelcontextprotocol.io/specification/2026-07-28/basic/security_best_practices" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/2026-07-28/basic/security_best_practices</a></li><li><a href="https://modelcontextprotocol.io/specification/2026-07-28/basic/transports" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/2026-07-28/basic/transports</a></li><li><a href="https://modelcontextprotocol.io/specification/2026-07-28/basic/transports/streamable-http" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/2026-07-28/basic/transports/streamable-http</a></li></ul>',20)])])}const b=t(r,[["render",i]]);export{f as __pageData,b as default};
